#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.Build;using UnityEditor.Build.Reporting;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.XR.OpenXR;using UnityEngine.XR.OpenXR.Features;using VRMaintenanceResearch.HandsLabQuest3.Runtime;
namespace VRMaintenanceResearch.HandsLabQuest3.Editor {
public static partial class HandsLabEditor {
public const string TestApplicationId="th.ac.tmu.vr.handslab.quest3.technical";
static partial void BuildCommand(string command){if(command=="apk")BuildApk();else if(command=="features")FeatureProbe();else SimulatorCommand(command);}
static partial void SimulatorCommand(string command);
[MenuItem("Tools/Quest 3 HandsLab/Open Lab")] static void OpenLab(){Guard();EditorSceneManager.OpenScene(ScenePath);}
[MenuItem("Tools/Quest 3 HandsLab/Build Android Development APK")] public static void BuildApk(){Guard();Checks();if(EditorUserBuildSettings.activeBuildTarget!=BuildTarget.Android)throw new Exception("HandsLab build requires active Android target");var target=NamedBuildTarget.Android;string oldId=PlayerSettings.GetApplicationIdentifier(target);string oldProduct=PlayerSettings.productName;var oldTarget=PlayerSettings.Android.targetSdkVersion;bool oldCustom=PlayerSettings.Android.useCustomKeystore;bool oldBundle=EditorUserBuildSettings.buildAppBundle,oldExport=EditorUserBuildSettings.exportAsGoogleAndroidProject;var oldBackend=PlayerSettings.GetScriptingBackend(target);var settings=OpenXRSettings.GetSettingsForBuildTargetGroup(BuildTargetGroup.Android);var features=settings.GetFeatures<OpenXRFeature>();var saved=features.ToDictionary(f=>f,f=>f.enabled);var session=UnityEngine.Object.FindFirstObjectByType<HandsLabSession>();string oldEnv=session.executionEnvironment;string apk=Out+"/Build/HandsLabQuest3_"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss",System.Globalization.CultureInfo.InvariantCulture)+".apk";Directory.CreateDirectory(Out+"/Build");try{PlayerSettings.productName="HandsLab Quest3 Technical";EditorUserBuildSettings.buildAppBundle=false;EditorUserBuildSettings.exportAsGoogleAndroidProject=false;PlayerSettings.SetApplicationIdentifier(target,TestApplicationId);PlayerSettings.Android.targetSdkVersion=AndroidSdkVersions.AndroidApiLevel35;PlayerSettings.Android.useCustomKeystore=false;PlayerSettings.SetScriptingBackend(target,ScriptingImplementation.IL2CPP);string[] required={"HandTracking","MetaHandTrackingAim","OculusTouchControllerProfile","MetaQuestTouchPlusControllerProfile","MetaQuestFeature"};foreach(string type in required){var f=features.FirstOrDefault(x=>x.GetType().Name==type);if(!f)throw new Exception("Required OpenXR feature not found: "+type);f.enabled=true;}session.executionEnvironment="QuestStandalone";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());Write("build_configuration",new{applicationIdentifier=TestApplicationId,productName=PlayerSettings.productName,development=true,backend="IL2CPP",architecture=PlayerSettings.Android.targetArchitectures.ToString(),targetSdk=35,graphicsAPIs=PlayerSettings.GetGraphicsAPIs(BuildTarget.Android).Select(v=>v.ToString()).ToArray(),features=features.Where(f=>f.enabled).Select(f=>f.GetType().FullName).ToArray(),scene=ScenePath,output=apk,hardwareVerified=false});var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{ScenePath},locationPathName=apk,target=BuildTarget.Android,options=BuildOptions.Development});Write("build_result",new{passed=report.summary.result==BuildResult.Succeeded,result=report.summary.result.ToString(),report.summary.totalErrors,report.summary.totalWarnings,totalSeconds=report.summary.totalTime.TotalSeconds,report.summary.totalSize,output=apk,messages=report.steps.SelectMany(s=>s.messages).Where(m=>m.type==LogType.Error||m.type==LogType.Exception).Select(m=>m.content).ToArray()});if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Android build failed; see build_result.json");}finally{PlayerSettings.productName=oldProduct;EditorUserBuildSettings.buildAppBundle=oldBundle;EditorUserBuildSettings.exportAsGoogleAndroidProject=oldExport;var live=UnityEngine.Object.FindFirstObjectByType<HandsLabSession>();if(live){live.executionEnvironment=oldEnv;EditorUtility.SetDirty(live);}EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());bool envRestored=live&&live.executionEnvironment==oldEnv;foreach(var pair in saved)pair.Key.enabled=pair.Value;AssetDatabase.SaveAssetIfDirty(settings);PlayerSettings.SetApplicationIdentifier(target,oldId);PlayerSettings.Android.targetSdkVersion=oldTarget;PlayerSettings.Android.useCustomKeystore=oldCustom;PlayerSettings.SetScriptingBackend(target,oldBackend);File.Copy(ScenePath,Out+"/MODIFIED_FILE.unity",true);Write("build_settings_restored",new{executionEnvironment=oldEnv,executionEnvironmentRestored=envRestored,productName=PlayerSettings.productName,originalProductName=oldProduct,applicationIdentifier=PlayerSettings.GetApplicationIdentifier(target),originalApplicationIdentifier=oldId,featuresRestored=saved.All(x=>x.Key.enabled==x.Value),targetSdk=PlayerSettings.Android.targetSdkVersion.ToString(),customKeystore=PlayerSettings.Android.useCustomKeystore,backend=PlayerSettings.GetScriptingBackend(target).ToString()});}}
static void FeatureProbe(){Write("features",new[]{BuildTargetGroup.Android,BuildTargetGroup.Standalone}.Select(t=>new{target=t.ToString(),features=OpenXRSettings.GetSettingsForBuildTargetGroup(t).GetFeatures<OpenXRFeature>().Select(f=>new{type=f.GetType().FullName,f.enabled}).ToArray()}));}
}}
#endif
